import Base from '../layouts/Base.astro';
---
<Base title="Berries">
  <h1>Berries</h1>
  <ul id="berries"><li>Loading…</li></ul>
  <script>
    fetch('https://pokeapi.co/api/v2/berry?limit=12')
      .then((response) => response.json())
      .then((data) => {
        document.querySelector('#berries').innerHTML =
          data.results.map((berry) => `<li>${berry.name}</li>`).join('');
      });
  </script>
</Base>

import Base from '../layouts/Base.astro';

const response = await fetch('https://pokeapi.co/api/v2/berry?limit=12');
if (!response.ok) throw new Error(`PokéAPI answered ${response.status}`);
const { results: berries } = await response.json();
---
<Base title="Berries">
  <h1>Berries</h1>
  <ul>
    {berries.map((berry) => <li>{berry.name}</li>)}
  </ul>
</Base>

